from pathlib import Path
import base64
import gzip
import subprocess

ROOT=Path(__file__).resolve().parents[2]
PAYLOAD=''''''
patch_bytes=gzip.decompress(base64.b64decode(PAYLOAD))
proc=subprocess.run(['patch','-p1','--batch','--forward'],cwd=ROOT,input=patch_bytes)
if proc.returncode:
    raise SystemExit(proc.returncode)
source=(ROOT/'working_source/app/reno_scan_updater.py').read_text(encoding='utf-8')
assert "OCR_CACHE_VERSION = 'v7'" in source
assert 'class MsaConfirmDialog(tk.Toplevel):' in source
assert "text='Save Changes & Cancel MSA'" in source
assert (ROOT/'working_source/tests/regression_post_v96_msa_editable_fields.py').is_file()
print('Applied v97 MSA/OCR patch payload.')
